use std::collections::HashMap;

struct Memo { cache: HashMap<u64, u64> }

impl Memo {
    fn fib(&mut self, n: u64) -> u64 {
        if let Some(&v) = self.cache.get(&n) { return v; }
        let v = if n < 2 { n } else { self.fib(n - 1) + self.fib(n - 2) };
        self.cache.insert(n, v);
        v
    }
}

